package com.wissenup.domain.fee.entity; import jakarta.persistence.*;import lombok.*;import java.time.*;
@Entity @Table(name="fee_types") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class FeeType{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="fee_type_id")private Long feeTypeId;@Column(name="organization_id")private Long organizationId;@Column(name="fee_name")private String feeName;private String description;@Column(name="is_recurring")private Boolean isRecurring;private String status;@Column(name="created_at")private LocalDateTime createdAt;@Column(name="created_by")private Long createdBy;@Column(name="updated_at")private LocalDateTime updatedAt;@Column(name="updated_by")private Long updatedBy;@PrePersist void c(){if(status==null)status="ACTIVE";if(isRecurring==null)isRecurring=false;if(createdAt==null)createdAt=LocalDateTime.now();}@PreUpdate void u(){updatedAt=LocalDateTime.now();}}
